// Shared world state for the two roaming characters -- Mochi the cat
// (chatbot/Pet.js) and the flying dreamer (dreamer/Dreamer.js) -- so each can
// react to the other without importing it. Plain module state: each writes its
// own snapshot every frame and reads the other's. Screen coordinates (px,
// y down) throughout.
//
//   companions.dreamer  {x, y (feet), headX, headY, airborne, alt, shadowX,
//                        carrying, at}
//   companions.pet      {x, y (feet), free, onFloor, at}
//   companions.carry    the scoop handshake, owned jointly:
//     dreamer sets {state: "requested", x, y}  (x, y = where his hands are)
//     pet answers  "held"  (or clears it to decline)
//     dreamer keeps x, y, vx, vy updated while held
//     either ends it: dreamer "released" (with vx, vy), pet "cancelled"
//     (someone grabbed the cat) -- the other side clears it.
//
// Events: "dreamerLanded" {x, y}, "petPounce" {x, y}.

export const companions = { dreamer: null, pet: null, carry: null };

const listeners = {};

export const on = (type, fn) => {
  if (!listeners[type]) listeners[type] = [];
  listeners[type].push(fn);
  return () => {
    listeners[type] = (listeners[type] || []).filter((f) => f !== fn);
  };
};

export const emit = (type, data) => {
  (listeners[type] || []).slice().forEach((fn) => {
    try {
      fn(data);
    } catch (e) {
      /* one character misbehaving must never break the other */
    }
  });
};

// A snapshot older than this means that character isn't running (unmounted,
// paused, tab hidden) -- ignore it rather than react to a ghost.
export const fresh = (snap, ms = 300) =>
  !!snap && performance.now() - snap.at < ms;
